-- Per-thread AI reply cap.
--
-- Bounds how many times the AI may reply into one customer conversation
-- before the thread is escalated for a human reply. A single comment was
-- already safe from a double reply (the atomic claims in
-- workers/ai-responder.worker.ts), but a conversation was not: each new
-- reply from the same customer arrives as its own PENDING Comment row and
-- earned its own AI reply, with no accounting across the exchange.
--
-- Hand-written rather than generated by `prisma migrate dev`, per
-- prisma/migrations/README.md: the direct connection Prisma Migrate needs
-- (DIRECT_URL, port 5432) is not reachable from the dev machine, only the
-- pooled DATABASE_URL (6543). Apply via the Supabase SQL Editor, then fold
-- into a real migration file from an environment that can reach DIRECT_URL.
--
-- Safe to re-run: every statement is guarded.

-- The cap itself. 0 means no limit. Default 3 is deliberately a real cap
-- rather than unlimited -- existing workspaces adopt the limit on apply.
ALTER TABLE "Workspace"
  ADD COLUMN IF NOT EXISTS "maxAiRepliesPerThread" INTEGER NOT NULL DEFAULT 3;

-- Marks a comment whose reply came from an autonomous path (the AI responder
-- worker, or POST /api/mcp/respond-to-item) rather than a human using the
-- Inbox. This is what the cap counts.
--
-- NOT backfilled, and deliberately not backfillable: before this column
-- existed, an AI reply and a human reply were written identically (status
-- RESPONDED + finalResponse), so there is no signal in the existing rows to
-- recover the distinction from. Every conversation that predates this
-- migration therefore starts with a full budget, which is the forgiving
-- direction -- the alternative would be guessing, and guessing wrong would
-- silently gag the AI on live threads.
ALTER TABLE "Comment"
  ADD COLUMN IF NOT EXISTS "aiResponded" BOOLEAN NOT NULL DEFAULT false;

-- Supports the per-thread count in lib/comment-thread.ts, which filters on
-- exactly this pair before narrowing by author. Without it the count is a
-- sequential scan of Comment on every AI reply decision.
CREATE INDEX IF NOT EXISTS "Comment_socialAccountId_platformPostId_idx"
  ON "Comment"("socialAccountId", "platformPostId");
